# Host Tool Permission System — WebChat Extension

Reference for adding a user-approved, host-executed tool layer to the
Floki WebChat at `~/Desktop/model/gemma4/webchat/`. The base chat is a
Node.js backend (`server.js`) with a vanilla-JS frontend. The scanner and
utility ecosystem on this host is Python-first, so the tools themselves live
in Python and are driven from Node via a bridge.

## When to use

- User asks for the WebChat to "run tools on the host" or "give the model
  permission to execute commands / scan / search files / etc."
- The existing WebChat already streams chat via SSE and persists messages
  in SQLite.
- You want real execution, not mocked output, but the user must approve
  each tool invocation.

## Architecture

```
webchat/
├── server.js                       # Node backend — chat SSE + approval endpoints
├── public/
│   ├── app.js                      # renders permission cards + tool result panels
│   └── style.css                   # terminal-like tool result theme tokens
└── tools/
    ├── tool_registry.py            # Python implementations of host tools
    └── tool_registry_bridge.js     # Node ↔ Python child_process wrapper
```

The model does NOT run tools directly. It emits a structured `tool_request`
that the backend surfaces as an SSE event. The frontend renders a
permission card; the user chooses **Allow**, **Allow Once**, or **Deny**.
Only then does the backend call the bridge, execute the tool, and stream
the result back.

## 1. Python tool registry (`tools/tool_registry.py`)

A single-file registry with metadata, validation, and safe execution.

```python
#!/usr/bin/env python3
"""Host tool registry for the WebChat backend."""
import json, sys, subprocess, time, shlex, os, re, textwrap

SAFE = re.compile(r"^[A-Za-z0-9_./:@+=\-?&|\"'\[\]{}\s\$\*\~\`]+$")

TOOLS = {
    "terminal": {
        "description": "Run a host shell command and return stdout/stderr/exit_code.",
        "args": {"command": "string", "timeout": "number"},
        "timeout": 60,
    },
    "curl": {
        "description": "Fetch a URL with curl; returns status, headers, body excerpt.",
        "args": {"url": "string", "method": "string", "max_time": "number"},
        "timeout": 30,
    },
    "nmap": {
        "description": "Port-scan a host with safe default flags.",
        "args": {"target": "string", "ports": "string", "flags": "string"},
        "timeout": 120,
    },
    "search_files": {
        "description": "Ripgrep search in files.",
        "args": {"pattern": "string", "path": "string", "output_mode": "string"},
        "timeout": 60,
    },
    "read_file": {
        "description": "Read a text file with pagination.",
        "args": {"path": "string", "offset": "number", "limit": "number"},
        "timeout": 10,
    },
    "write_file": {
        "description": "Write content to a file.",
        "args": {"path": "string", "content": "string"},
        "timeout": 10,
    },
}

def run_terminal(command, timeout=60):
    # Allow-list: no shell metacharacters outside a curated set.
    if not SAFE.match(command):
        return {"ok": False, "error": "command contains disallowed characters"}
    start = time.time()
    try:
        r = subprocess.run(
            command, shell=True, capture_output=True, text=True,
            timeout=max(1, int(timeout)), cwd=os.getcwd(),
        )
        return {
            "ok": True, "exit_code": r.returncode,
            "stdout": r.stdout, "stderr": r.stderr,
            "duration_ms": int((time.time() - start) * 1000),
        }
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": f"timed out after {timeout}s"}
    except Exception as e:
        return {"ok": False, "error": str(e)}

def run_curl(url, method="GET", max_time=30):
    cmd = ["curl", "-sS", "-L", "-m", str(max_time), "-X", method.upper(), url]
    return run_terminal(shlex.join(cmd), timeout=max_time + 5)

def run_nmap(target, ports=None, flags="-sV --top-ports 100 -T4"):
    cmd = f"nmap {flags} {target}"
    if ports:
        cmd = f"nmap {flags} -p {ports} {target}"
    return run_terminal(cmd, timeout=120)

def run_search_files(pattern, path=".", output_mode="files_only"):
    valid_modes = {"files_only", "content", "count"}
    if output_mode not in valid_modes:
        return {"ok": False, "error": f"output_mode must be one of {valid_modes}"}
    flags = "-l" if output_mode == "files_only" else "-n" if output_mode == "content" else "-c"
    cmd = f"rg {flags} --no-heading -e {shlex.quote(pattern)} {shlex.quote(path)}"
    return run_terminal(cmd, timeout=60)

def run_read_file(path, offset=1, limit=500):
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.readlines()
        start = max(0, int(offset) - 1)
        end = start + int(limit)
        return {
            "ok": True, "path": path, "offset": int(offset), "limit": int(limit),
            "total_lines": len(lines),
            "content": "".join(lines[start:end]),
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}

def run_write_file(path, content):
    try:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        return {"ok": True, "path": path, "bytes": len(content.encode("utf-8"))}
    except Exception as e:
        return {"ok": False, "error": str(e)}

RUNNERS = {
    "terminal": run_terminal,
    "curl": run_curl,
    "nmap": run_nmap,
    "search_files": run_search_files,
    "read_file": run_read_file,
    "write_file": run_write_file,
}

def list_tools():
    return [{"name": k, **{k2: v2 for k2, v2 in v.items() if k2 != "timeout"}}
            for k, v in TOOLS.items()]

def run_tool(name, params):
    if name not in RUNNERS:
        return {"ok": False, "error": f"unknown tool: {name}"}
    fn = RUNNERS[name]
    try:
        sig = set(TOOLS[name]["args"].keys())
        kwargs = {k: v for k, v in params.items() if k in sig}
        return fn(**kwargs)
    except Exception as e:
        return {"ok": False, "error": str(e)}

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(json.dumps({"ok": False, "error": "usage: tool_registry.py list | run <json-name> <json-params>"}))
        sys.exit(1)
    if sys.argv[1] == "list":
        print(json.dumps(list_tools()))
    elif sys.argv[1] == "run":
        # Node passes JSON.stringify(name) and JSON.stringify(params).
        name = json.loads(sys.argv[2])
        params = json.loads(sys.argv[3]) if len(sys.argv) > 3 else {}
        print(json.dumps(run_tool(name, params)))
    else:
        print(json.dumps({"ok": False, "error": f"unknown command: {sys.argv[1]}"}))
```

### Key pitfalls of the Python side

- **Always JSON-stringify BOTH args from Node.** If you only stringify the
  params and pass the tool name raw, the name arrives with literal quotes
  (`"terminal"`) and Python reports `unknown tool: "terminal"`. The fix is
  `json.loads(sys.argv[2])`.
- **Never pass user input directly to `shell=True` without allow-listing.**
  The `SAFE` regex above permits common flags but blocks backticks,
  semicolons, newlines, and chained commands. For a hacker-focused UI this
  balance matters: power users need pipes and globs, but arbitrary input
  must not become a remote shell.
- **Return a stable shape.** Every tool returns `{"ok", ...}` so the Node
  bridge and frontend can render success/failure consistently.
- **Use `cwd=os.getcwd()` explicitly** in `subprocess.run` so relative paths
  resolve to the WebChat working directory, not the Python process's
  inherited cwd.

## 2. Node bridge (`tools/tool_registry_bridge.js`)

```js
const { spawnSync } = require('child_process');
const path = require('path');

const SCRIPT = path.join(__dirname, 'tool_registry.py');

function list() {
  const r = spawnSync('python3', [SCRIPT, 'list'], {
    encoding: 'utf8', timeout: 10000, maxBuffer: 16 * 1024 * 1024,
  });
  return JSON.parse(r.stdout || '[]');
}

function run(name, params = {}) {
  const r = spawnSync('python3', [
    SCRIPT, 'run', JSON.stringify(name), JSON.stringify(params),
  ], {
    encoding: 'utf8', timeout: 180000, maxBuffer: 64 * 1024 * 1024,
  });
  if (r.status !== 0) {
    return { ok: false, error: r.stderr || 'bridge failed', exit_code: r.status };
  }
  try {
    return JSON.parse(r.stdout);
  } catch (e) {
    return { ok: false, error: 'invalid JSON from tool registry', raw: r.stdout, stderr: r.stderr };
  }
}

module.exports = { list, run };
```

### Verification

```bash
cd ~/Desktop/model/gemma4/webchat
python3 tools/tool_registry.py terminal '{"command":"echo hello registry"}'
# → {"ok": true, "exit_code": 0, "stdout": "hello registry\n", ...}

node -e "const t=require('./tools/tool_registry_bridge.js'); console.log(t.run('terminal',{command:'echo bridge works'}));"
# → { ok: true, exit_code: 0, stdout: 'bridge works\n', ... }
```

## 3. Backend integration

Import the bridge near the top of `server.js`:

```js
const TOOL_REGISTRY = require('./tools/tool_registry_bridge.js');
```

Add three endpoints:

```js
// GET /api/tools/list  →  list available tools (for model context + UI)
app.get('/api/tools/list', (req, res) => {
  res.json({ tools: TOOL_REGISTRY.list() });
});

// POST /api/tools/ask  →  model asks to run a tool; backend emits SSE event
// (usually called internally from the chat SSE handler, not by the client)

// POST /api/tools/approve  →  user allows/denies a pending tool call
app.post('/api/tools/approve', async (req, res) => {
  const { call_id, decision } = req.body; // decision: 'allow' | 'allow_once' | 'deny'
  const pending = pendingTools.get(call_id);
  if (!pending) return res.status(404).json({ ok: false, error: 'no pending tool call' });

  if (decision === 'deny') {
    pending.resolve({ ok: false, error: 'user denied' });
  } else {
    const result = TOOL_REGISTRY.run(pending.name, pending.params);
    pending.resolve(result);
  }
  pendingTools.delete(call_id);
  res.json({ ok: true });
});
```

Inside the chat SSE handler, when the model emits a `tool_request`, pause
token accumulation and emit:

```js
send('tool_request', {
  call_id: callId,
  name: toolName,
  params: toolParams,
  description: toolDescription,
});
```

Then wait for the user decision via `pendingTools` (a `Map` of `call_id`
→ `{ name, params, resolve }`). When resolved, emit:

```js
send('tool_result', { call_id: callId, result });
```

Finally append the tool result to the conversation context (as a
`tool` role message or a system note) and continue streaming the model's
response.

## 4. Frontend permission card + result panel

