# Ollama SSE proxy — tested core

Working pieces extracted from a verified build (floki-k8 / gemma4 via
Ollama at 127.0.0.1:11434, Node 22+, node:sqlite). Reproduce with
modifications.

## SQLite schema (node:sqlite)

```js
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync(DB_PATH);
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE IF NOT EXISTS conversations (
    id TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT 'New chat',
    model TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
  CREATE TABLE IF NOT EXISTS messages (
    id TEXT PRIMARY KEY, conv_id TEXT NOT NULL, role TEXT NOT NULL,
    content TEXT NOT NULL, images TEXT, thinking TEXT, created_at INTEGER NOT NULL,
    FOREIGN KEY (conv_id) REFERENCES conversations(id) ON DELETE CASCADE);
  CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
  CREATE INDEX IF NOT EXISTS idx_msg_conv ON messages(conv_id, created_at);
`);
// Prepared statements: db.prepare('INSERT ...'), .run(...), .all(...), .get(...)
// Settings stored JSON-encoded: setSetting.run(k, JSON.stringify(v))
```

## The NDJSON -> SSE chat proxy (the heart)

Ollama `/api/chat` with `stream:true` returns newline-delimited JSON, NOT
SSE. Parse NDJSON, re-emit SSE.

```js
async function handleChat(req, res) {
  const body = await readBody(req);            // {conversation_id, model, content, images:[dataURL]}
  const settings = loadSettings();
  const model = body.model || settings.model;

  let convId = body.conversation_id;
  if (!convId) { convId = uid(); stmt.insertConv.run(convId, (body.content||'New chat').slice(0,60), model, now(), now()); }

  // persist user msg (images as full data URLs for redisplay)
  const userImages = Array.isArray(body.images) ? body.images : [];
  stmt.insertMsg.run(uid(), convId, 'user', body.content||'',
    userImages.length ? JSON.stringify(userImages) : null, null, now());

  // assemble FULL multi-turn history
  const messages = [];
  if (settings.system) messages.push({ role:'system', content: settings.system });
  for (const m of stmt.listMsg.all(convId)) {
    const msg = { role:m.role, content:m.content };
    if (m.images) { try { msg.images = JSON.parse(m.images).map(d => d.replace(/^data:[^;]+;base64,/,'')); } catch{} }
    messages.push(msg);                        // STRIP data: prefix -> raw base64 for Ollama
  }

  const options = { temperature:settings.temperature, top_p:settings.top_p,
    top_k:settings.top_k, repeat_penalty:settings.repeat_penalty, num_ctx:settings.num_ctx };

  res.writeHead(200, { 'Content-Type':'text/event-stream', 'Cache-Control':'no-cache',
    'Connection':'keep-alive', 'X-Accel-Buffering':'no' });
  const send = (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  send('meta', { conversation_id: convId });

  let full='', thinking='', aborted=false;
  req.on('close', () => { aborted = true; });   // cancel upstream if client leaves

  const upstream = await fetch(OLLAMA+'/api/chat', { method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ model, messages, stream:true, options }) });
  if (!upstream.ok) { send('error', { error:`ollama ${upstream.status}: ${await upstream.text()}` }); return res.end(); }

  const reader = upstream.body.getReader(); const dec = new TextDecoder(); let buf='';
  while (true) {
    if (aborted) { try { await reader.cancel(); } catch{} break; }
    const { done, value } = await reader.read(); if (done) break;
    buf += dec.decode(value, { stream:true });
    let i; while ((i = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0,i).trim(); buf = buf.slice(i+1); if (!line) continue;
      let obj; try { obj = JSON.parse(line); } catch { continue; }
      if (obj.message) {
        if (obj.message.thinking) { thinking += obj.message.thinking; send('thinking', { delta: obj.message.thinking }); }
        if (obj.message.content)  { full     += obj.message.content;  send('token',    { delta: obj.message.content  }); }
      }
      if (obj.done) send('done', { eval_count: obj.eval_count, total_duration: obj.total_duration, prompt_eval_count: obj.prompt_eval_count });
    }
  }
  if (full || thinking) {                        // don't persist a half msg on abort
    stmt.insertMsg.run(uid(), convId, 'assistant', full, null, thinking||null, now());
    stmt.touchConv.run(now(), model, convId);
    send('saved', {});
  }
  res.end();
}
```

## Model load / unload

```js
// warm into VRAM
await fetch(OLLAMA+'/api/chat',    { method:'POST', body: JSON.stringify({ model, messages:[], stream:false }) });
// free VRAM
await fetch(OLLAMA+'/api/generate',{ method:'POST', body: JSON.stringify({ model, keep_alive:0 }) });
// capabilities (does it have 'thinking' / 'tools' / vision?)
const show = await (await fetch(OLLAMA+'/api/show', { method:'POST', body: JSON.stringify({ name: model }) })).json();
// show.capabilities -> ['completion','tools','thinking']
```

## Vision capability detection + image stripping (prevents the 400)

The chat-proxy snippet above attaches `msg.images` unconditionally — that
is the BUG. A text-only model returns HTTP 400 "Multimodal data provided,
but model does not support multimodal requests" and fails the whole turn,
and the stored image keeps re-failing every later text turn. Replace the
unconditional attach with capability-gated attach:

```js
// cache: model name -> bool
const visionCache = new Map();
async function modelSupportsVision(name) {
  if (visionCache.has(name)) return visionCache.get(name);
  let ok = false;
  try {
    const d = await (await fetch(OLLAMA+'/api/show', { method:'POST',
      body: JSON.stringify({ name }) })).json();
    const caps = d.capabilities || [];
    const fams = d.details?.families || [];
    ok = caps.includes('vision') || fams.some(f => /clip|vision|mllama|llava/i.test(f));
  } catch { ok = false; }
  visionCache.set(name, ok);
  return ok;
}

// in handleChat, when assembling history:
const supportsVision = await modelSupportsVision(model);
for (const m of stmt.listMsg.all(convId)) {
  const msg = { role:m.role, content:m.content };
  if (m.images && supportsVision) {            // <-- gate on capability
    try { msg.images = JSON.parse(m.images).map(d => d.replace(/^data:[^;]+;base64,/,'')); } catch{}
  }
  messages.push(msg);
}

// right after send('meta', ...):
if (userImages.length && !supportsVision) {
  send('notice', { message: `${model} is text-only — image(s) ignored for this reply. Load a vision model to use images.` });
}
```

Front-end: handle `ev.event==='notice'` by showing a toast. Images stay
stored on the user row for redisplay regardless; they're just not
forwarded to a model that can't use them.

## EADDRINUSE — graceful listen, never crash-dump

Node's default on a busy port is an unhandled-error stack trace. Wrap
`listen` so it either auto-tries the next port or prints a clear message:

```js
function startServer(port, attemptsLeft = 10) {
  server.once('error', (err) => {
    if (err.code === 'EADDRINUSE') {
      if (process.env.PORT) {                    // user pinned a port -> don't roam
        console.error(`Port ${port} already in use. Open http://localhost:${port} or run stop.sh.`);
        process.exit(1);
      }
      if (attemptsLeft > 0) { setTimeout(() => startServer(port+1, attemptsLeft-1), 150); return; }
      console.error(`No free port near ${PORT}.`); process.exit(1);
    }
    console.error('Server error:', err); process.exit(1);
  });
  server.listen(port, () => console.log(`WebChat: http://localhost:${port}`));
}
startServer(Number(PORT));
```

stop.sh: `lsof -ti tcp:"${PORT:-8123}" | xargs kill -9`

## Browser-side SSE parser

```js
const res = await fetch('/api/chat', { method:'POST', headers:{'Content-Type':'application/json'},
  body: JSON.stringify({ conversation_id, model, content, images }), signal: ctrl.signal });
const reader = res.body.getReader(); const dec = new TextDecoder(); let buf='';
while (true) {
  const { done, value } = await reader.read(); if (done) break;
  buf += dec.decode(value, { stream:true });
  let i; while ((i = buf.indexOf('\n\n')) >= 0) {       // SSE frames split on blank line
    const chunk = buf.slice(0,i); buf = buf.slice(i+2);
    let event='message', data='';
    for (const ln of chunk.split('\n')) {
      if (ln.startsWith('event:')) event = ln.slice(6).trim();
      else if (ln.startsWith('data:')) data += ln.slice(5).trim();
    }
    if (!data) continue; const ev = { event, data: JSON.parse(data) };
    if (ev.event==='meta')     { /* capture conversation_id, refresh sidebar */ }
    if (ev.event==='thinking') { /* append to a <details> reasoning panel */ }
    if (ev.event==='token')    { /* append to answer, re-render markdown */ }
    if (ev.event==='done')     { /* tok/s = eval_count / (total_duration/1e9) */ }
  }
}
// Stop button: const ctrl = new AbortController(); ctrl.abort() to cancel.
```

## start.sh launcher

```bash
#!/bin/bash
cd "$(dirname "$0")"
PORT="${PORT:-8123}"; OLLAMA_HOST="${OLLAMA_HOST:-http://127.0.0.1:11434}"
if ! curl -s "$OLLAMA_HOST/api/tags" >/dev/null 2>&1; then
  (ollama serve >/tmp/ollama.log 2>&1 &); sleep 2
fi
PORT="$PORT" OLLAMA_HOST="$OLLAMA_HOST" exec node server.js
```

