node -e "console.log(typeof require('node:sqlite').DatabaseSync)"   # function => OK
curl -s localhost:8123/api/models | python3 -c "import sys,json;print(len(json.load(sys.stdin)['models']))"
curl -sN -X POST localhost:8123/api/chat -H 'Content-Type: application/json' \
