  font-family:inherit;transition:filter .15s;
}
.vision-banner .banner-btn:hover{filter:brightness(1.3)}
.vision-banner .banner-x{
  background:none;border:none;color:#1a0f00;cursor:pointer;
  font-size:18px;line-height:1;padding:0 4px;opacity:.5;
}
.vision-banner .banner-x:hover{opacity:1}
@keyframes slideDown{
  from{opacity:0;transform:translateY(-6px)}
